PRAGMA foreign_keys=OFF;
DROP TABLE IF EXISTS moderation_cases;DROP TABLE IF EXISTS platform_settings;DROP TABLE IF EXISTS audit_events;DROP TABLE IF EXISTS usage_records;DROP TABLE IF EXISTS conversation_shares;DROP TABLE IF EXISTS citations;DROP TABLE IF EXISTS chat_events;DROP TABLE IF EXISTS chat_runs;DROP TABLE IF EXISTS messages;DROP TABLE IF EXISTS provider_credentials;DROP TABLE IF EXISTS conversation_tools;DROP TABLE IF EXISTS tools;DROP TABLE IF EXISTS knowledge_chunks;DROP TABLE IF EXISTS ingestion_jobs;DROP TABLE IF EXISTS knowledge_files;DROP TABLE IF EXISTS conversations;DROP TABLE IF EXISTS knowledge_collections;DROP TABLE IF EXISTS user_model_settings;DROP TABLE IF EXISTS models;DROP TABLE IF EXISTS prompt_templates;DROP TABLE IF EXISTS password_reset_tokens;DROP TABLE IF EXISTS sessions;DROP TABLE IF EXISTS users;
PRAGMA foreign_keys=ON;
CREATE TABLE users(id INTEGER PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user',status TEXT NOT NULL DEFAULT 'active',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL);
CREATE TABLE password_reset_tokens(id INTEGER PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,user_id INTEGER NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL,used_at TEXT);
CREATE TABLE models(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,provider TEXT NOT NULL,description TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,max_temperature REAL NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE user_model_settings(user_id INTEGER PRIMARY KEY REFERENCES users(id),model_id INTEGER NOT NULL REFERENCES models(id),temperature REAL NOT NULL DEFAULT 0.2,max_tokens INTEGER NOT NULL DEFAULT 500,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE prompt_templates(id INTEGER PRIMARY KEY,owner_id INTEGER REFERENCES users(id),name TEXT NOT NULL,content TEXT NOT NULL,is_global INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,UNIQUE(owner_id,name));
CREATE TABLE knowledge_collections(id INTEGER PRIMARY KEY,owner_id INTEGER NOT NULL REFERENCES users(id),name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,UNIQUE(owner_id,name));
CREATE TABLE conversations(id INTEGER PRIMARY KEY,owner_id INTEGER NOT NULL REFERENCES users(id),title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',knowledge_collection_id INTEGER REFERENCES knowledge_collections(id),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE knowledge_files(id INTEGER PRIMARY KEY,collection_id INTEGER NOT NULL REFERENCES knowledge_collections(id) ON DELETE CASCADE,filename TEXT NOT NULL,mime_type TEXT NOT NULL,bytes BLOB NOT NULL,status TEXT NOT NULL DEFAULT 'ready',created_at TEXT NOT NULL,UNIQUE(collection_id,filename));
CREATE TABLE ingestion_jobs(id INTEGER PRIMARY KEY,file_id INTEGER NOT NULL UNIQUE REFERENCES knowledge_files(id) ON DELETE CASCADE,status TEXT NOT NULL,chunk_count INTEGER NOT NULL,error TEXT,created_at TEXT NOT NULL,completed_at TEXT);
CREATE TABLE knowledge_chunks(id INTEGER PRIMARY KEY,file_id INTEGER NOT NULL REFERENCES knowledge_files(id) ON DELETE CASCADE,position INTEGER NOT NULL,text TEXT NOT NULL);
CREATE TABLE tools(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,description TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE conversation_tools(conversation_id INTEGER NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,tool_id INTEGER NOT NULL REFERENCES tools(id),PRIMARY KEY(conversation_id,tool_id));
CREATE TABLE provider_credentials(id INTEGER PRIMARY KEY,owner_id INTEGER NOT NULL REFERENCES users(id),provider TEXT NOT NULL,label TEXT NOT NULL,secret_hash TEXT NOT NULL,last_four TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,UNIQUE(owner_id,provider,label));
CREATE TABLE messages(id INTEGER PRIMARY KEY,conversation_id INTEGER NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,role TEXT NOT NULL,content TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'visible',created_at TEXT NOT NULL);
CREATE TABLE chat_runs(id INTEGER PRIMARY KEY,conversation_id INTEGER NOT NULL REFERENCES conversations(id),user_message_id INTEGER NOT NULL REFERENCES messages(id),assistant_message_id INTEGER REFERENCES messages(id),model_id INTEGER NOT NULL REFERENCES models(id),status TEXT NOT NULL,output TEXT NOT NULL DEFAULT '',prompt_tokens INTEGER NOT NULL DEFAULT 0,completion_tokens INTEGER NOT NULL DEFAULT 0,idempotency_key TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL,completed_at TEXT);
CREATE TABLE chat_events(id INTEGER PRIMARY KEY,run_id INTEGER NOT NULL REFERENCES chat_runs(id) ON DELETE CASCADE,event_type TEXT NOT NULL,data TEXT NOT NULL,sequence INTEGER NOT NULL);
CREATE TABLE citations(id INTEGER PRIMARY KEY,run_id INTEGER NOT NULL REFERENCES chat_runs(id) ON DELETE CASCADE,file_id INTEGER NOT NULL REFERENCES knowledge_files(id),chunk_id INTEGER NOT NULL REFERENCES knowledge_chunks(id),excerpt TEXT NOT NULL);
CREATE TABLE conversation_shares(id INTEGER PRIMARY KEY,conversation_id INTEGER NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,owner_id INTEGER NOT NULL REFERENCES users(id),token_hash TEXT NOT NULL UNIQUE,expires_at TEXT,revoked_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE usage_records(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),run_id INTEGER NOT NULL UNIQUE REFERENCES chat_runs(id),model_id INTEGER NOT NULL REFERENCES models(id),prompt_tokens INTEGER NOT NULL,completion_tokens INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE audit_events(id INTEGER PRIMARY KEY,actor_id INTEGER REFERENCES users(id),action TEXT NOT NULL,subject TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE platform_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE moderation_cases(id INTEGER PRIMARY KEY,message_id INTEGER NOT NULL REFERENCES messages(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',resolution TEXT NOT NULL DEFAULT '',resolved_by INTEGER REFERENCES users(id),resolved_at TEXT,created_at TEXT NOT NULL);
